//! CABIN · SIM
//!   · yard: the track graph the extractor writes and the game reads
//!   · consts: every tunable number, tagged solid or assumed
//!   · signal: signals generated by rule, written into the yard by cabin-osm
//!   · route: every route a signal can set, built at load
//!   · interlock: the one function that clears a signal
//!   · train: train bodies, motion, and the occupancy the interlocking reads
//!   · World: the yard, the interlocking and the trains, stepped by ticks
//!   · NDLS: the New Delhi yard, baked into the build
//!
//! The seeded `Rng` arrives with traffic in B7: nothing in B4 is random.
//! `World::spawn` offers a train by hand until then.

pub mod consts;
pub mod interlock;
pub mod route;
pub mod signal;
pub mod train;
pub mod yard;

use std::collections::BTreeMap;

use consts::{BRAKE_MS2, SPEED_NORMAL_KMH, SPEED_REVERSE_KMH};
use interlock::{Aspect, Interlocking, Refusal};
use route::{Exit, Lie, PortalId, Res, RouteId, SignalId};
use train::{Occupancy, Train, TrainId, along, kmh};
use yard::{Junction, Yard};

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Action {
    SetRoute { entry: SignalId, exit: Exit },
    CancelRoute(RouteId),
}

#[derive(Clone, Debug, PartialEq)]
pub struct World {
    pub yard: Yard,
    pub lock: Interlocking,
    pub trains: BTreeMap<TrainId, Train>,
    pub tick: u64,
    next_train: TrainId,
}

impl World {
    pub fn new(yard: Yard) -> World {
        let routes = route::build_routes(&yard);
        let lock = Interlocking::new(&yard, routes);
        World { yard, lock, trains: BTreeMap::new(), tick: 0, next_train: 0 }
    }

    /// A refused action changes nothing: every check runs before the first
    /// write.
    pub fn apply(&mut self, a: Action) -> Result<(), Refusal> {
        let occ = self.occupancy();
        match a {
            Action::SetRoute { entry, exit } => self.lock.request(&self.yard, &occ, entry, exit).map(|_| ()),
            Action::CancelRoute(r) => {
                self.lock.cancel(&self.yard, &occ, r)?;
                // A train that can still stop at the signal gives the route
                // up; one that cannot runs on under the locks, which stay
                // for APPROACH_RELEASE_S.
                let entry = self.lock.routes()[r].entry;
                for t in self.trains.values_mut().filter(|t| t.route == Some(r)) {
                    let d = t.to_signal(&self.yard, entry).unwrap_or(0.0);
                    if t.v * t.v / (2.0 * BRAKE_MS2) <= d {
                        let s = &self.yard.signals[entry];
                        let k = (t.head..t.run.len()).find(|&i| t.run[i] == (s.edge, s.forward)).expect("the entry is on the run");
                        t.run.truncate(k + 1);
                        t.limit = Some((k, along(&self.yard, s.edge, s.forward, s.offset)));
                        t.next_signal = Some(entry);
                        t.leaving = None;
                        t.route = None;
                        t.vmax = kmh(SPEED_NORMAL_KMH);
                        self.lock.untake(r);
                    }
                }
                Ok(())
            }
        }
    }

    /// Offer a train of `len_m` at a portal: its head at the box edge, the
    /// rest of it still outside, at line speed or slower if the Home is
    /// close. Refused while the portal track is occupied or locked, or the
    /// block is still running out a departure.
    pub fn spawn(&mut self, portal: PortalId, len_m: f64) -> Result<TrainId, Refusal> {
        let y = &self.yard;
        let p = &y.portals[portal];
        let occ = self.occupancy();
        if let Some(by) = occ.on(p.edge, 0.0, y.edges[p.edge].len) {
            return Err(Refusal::Occupied { at: Res::Edge(p.edge), by });
        }
        if let Some(r) = self.lock.holder(Res::Edge(p.edge)) {
            return Err(r);
        }
        self.lock.line_clear(portal)?;
        // In from the box edge to the first signal facing this way.
        let g = y.graph();
        let mut run = vec![(p.edge, y.edges[p.edge].a == p.node)];
        let signal = loop {
            let (e, f) = *run.last().unwrap();
            let ahead = y.signals.iter().enumerate().filter(|(_, s)| s.edge == e && s.forward == f).min_by(|a, b| along(y, e, f, a.1.offset).total_cmp(&along(y, e, f, b.1.offset)));
            if let Some((k, _)) = ahead {
                break k;
            }
            match (g.at[y.head(e, f)], g.next(y, e, f).first()) {
                (Junction::Through, Some(&nx)) if run.len() < y.edges.len() => run.push(nx),
                _ => panic!("portal {} reaches no signal", p.name),
            }
        };
        let id = self.next_train;
        self.next_train += 1;
        let s = &y.signals[signal];
        let mut t = Train::new(id, len_m, run);
        t.limit = Some((t.run.len() - 1, along(y, s.edge, s.forward, s.offset)));
        t.next_signal = Some(signal);
        t.v = t.vmax.min(train::stop_speed(t.to_limit(y)));
        self.trains.insert(id, t);
        Ok(id)
    }

    pub fn step_ticks(&mut self, n: u32) {
        for _ in 0..n {
            self.step();
        }
    }

    fn step(&mut self) {
        self.tick += 1;
        self.lock.set_now(self.tick);
        let ids: Vec<TrainId> = self.trains.keys().copied().collect();
        for id in ids {
            self.take_route(id);
            let y = &self.yard;
            let t = self.trains.get_mut(&id).unwrap();
            t.advance(y);
            if t.route.is_some_and(|r| t.to_signal(y, self.lock.routes()[r].entry).is_none()) {
                t.route = None;
            }
            if t.gone_m >= t.len_m {
                let p = t.leaving.expect("only a leaving train runs off its run");
                self.trains.remove(&id);
                self.lock.train_left(p);
            }
        }
        let occ = self.occupancy();
        self.lock.release_behind(&self.yard, &occ);
    }

    /// A train whose next signal is off takes that signal's route: its run
    /// grows by the route's path and its authority moves to the exit.
    fn take_route(&mut self, id: TrainId) {
        let t = &self.trains[&id];
        let Some(s) = t.next_signal else { return };
        if t.route.is_some() {
            return;
        }
        let Some(r) = self.lock.takeable(s) else { return };
        self.lock.take(r, id);
        let y = &self.yard;
        let route = &self.lock.routes()[r];
        let t = self.trains.get_mut(&id).unwrap();
        for &e in &route.path[1..] {
            let (x, xf) = *t.run.last().unwrap();
            let node = y.head(x, xf);
            t.run.push((e, y.edges[e].a == node));
        }
        // ponytail: one speed for the whole route, the lower one if it sets
        // any point reverse; a per-point limit needs the point positions on
        // the run.
        let reverse = route.points.iter().any(|p| p.1 == Lie::Reverse);
        t.vmax = kmh(if reverse { SPEED_REVERSE_KMH } else { SPEED_NORMAL_KMH });
        t.route = Some(r);
        match route.exit {
            Exit::Berth { starter, .. } => {
                let x = &y.signals[starter];
                t.limit = Some((t.run.len() - 1, along(y, x.edge, x.forward, x.offset)));
                t.next_signal = Some(starter);
            }
            Exit::Portal(p) => {
                t.limit = None;
                t.next_signal = None;
                t.leaving = Some(p);
            }
        }
    }

    pub fn occupancy(&self) -> Occupancy {
        Occupancy { bodies: self.trains.iter().map(|(&id, t)| (id, t.body(&self.yard))).collect() }
    }

    pub fn aspect(&self, s: SignalId) -> Aspect {
        self.lock.aspect(s)
    }

    pub fn lie(&self, k: usize) -> Lie {
        self.lock.lie(k)
    }
}

/// The yard the game ships with, written by `cabin-osm`. Baked in, so the
/// page never fetches: the game plays the extract of `Yard::osm_base`.
pub const NDLS: &str = include_str!("../../../data/ndls.yard");

#[cfg(test)]
mod tests {
    #[test]
    fn the_baked_yard_parses() {
        let y = crate::yard::Yard::parse(crate::NDLS).expect("data/ndls.yard parses");
        assert_eq!(y.platforms.len(), 16);
    }
}
